// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));

        uint256 amount = 0.5 ether;
        vm.deal(sender, amount);

        vm.prank(sender);
        bool ok;
        try c.lockInGuess{value: amount}(guess) {
            ok = true;
        } catch {
            ok = false;
        }

        assertFalse(ok, "lockInGuess should revert with 0.5 ether");
    }
}
